const names:Record<string,string>={TRK:'Engineering / Track',SIG:'S&T / Signal',TRC:'TRD / Traction'};
const number=(n:number)=>n.toLocaleString('en-IN');
const percent=(n:number,d:number)=>d?Math.round(n/d*100):0;
const tomorrow=()=>new Date(Date.now()+86400000+330*60000).toISOString().slice(0,10);
const minute=clockMinute;
